const vstat=d=>{const n=mcount(d,PL.d.slice(0,7)),t=tgt(d),l=lastV(d),ls=l?` <small style="display:inline">last ${l}</small>`:'';return n?`<span class="b ${n>=t?'done':'planned'}">${n}/${t} visits</span>${ls}`:`<span class="b bad">Unvisited · 0/${t}</span>${ls}`};
