/* template picker state (same filters as the Plan tab) */
const TF={},TB={sel:''};let TPLREC={slots:[]},HOTMODE=false,HREC={doctorIds:[]};
const TDEFS=()=>[{k:'cls',l:'Class',o:['A','B','C']},{k:'area',l:'Brick',o:areas()},{k:'sp',l:'Specialty',o:SPEC()},{k:'ad',l:'Adoption',o:['High','Low']},{k:'need',l:'Visit status',o:[['unc','Unvisited this month'],['rem','Below frequency'],['full','Fully served']]}];
